#include <iostream>
#include <fstream>
#include <string>
#include <sstream> 

using namespace std; 

int main() 
{ 
    // Declare variables 
    string line; 
    int count = 0; 

    // Open the file 
    ifstream myfile("input.txt"); 

    // Read the file line by line 
    while (getline(myfile, line)) 
    { 
        // Split the line by any whitespaces 
        istringstream iss(line); 
        string word; 

        // Read the word 
        iss >> word; 

        // Count the occurrences of the word 
        count++; 
    } 

    // Display the result 
    cout << "Number of occurrences of the word '" << word << "': " << count << endl; 

    return 0; 
}

