def longest_common_subsequence(s1, s2):
    # Initialize all length-2 cells of a 2-D array
    res = [[[0 for col in range(len(s1))] for col in range(len(s2))] 
           for row in range(len(s1))]

    # Initialize all lengths of LCS
    lcs = [[0 for col in range(len(s1))] for row in range(len(s2))]

    # First row of LCS is empty
    lcs[0][0] = 0

    # Initialize length of LCS[i][j]
    def lcs_length(i, j):
        if i == 0 or j == 0:
            return 0

        # If there is a character in s1[i] and s2[j-1], add 1 to the length
        if s1[i] == s2[j-1]:
            lcs[i+1][j-1] += 1
        # If there is no such character, set the length to 0
        else:
            lcs[i+1][j] = 0

    # Initialize LCS from 1st row and 1st column
    lcs[1][0] = 1
    for i in range(1, len(s1)):
        for j in range(1, len(s2)):
            lcs_length(i, j-1)
            lcs[i+1][j] = max(lcs[i][j-1], lcs[i-1][j] + 1)

    # Backtracking from last row
    for i in range(len(s1)):
        for j in range(len(s2)):
            if s1[i] != s2[j]:
                lcs_length(i, j)

    # Backtracking from last column
    for j in range(len(s2)):
        for i in range(len(s1[0])):
            if s1[i][j] != s2[j]:
                lcs_length(i+1, 0)

    # Return the longest common subsequence
    return lcs[len(s1)-1][len(s2)-1]

